UPDATE site_page_sections s
JOIN site_pages p ON p.site_page_id=s.site_page_id
SET s.rows_json='[{"layout_type":"TEXT_TOP","eyebrow_text":"How Toinky Works","title_text":"One world. Many truths.","content_html":"<p>Everyone enters the same story, but no one receives the same information. Your character history, relationships, and private choices shape what you believe and what happens next.</p>","columns":[{"icon_text":"01","title":"Choose a story","content":"<p>Enter a world built around tension, secrets, and meaningful choices.</p>"},{"icon_text":"02","title":"Gather your cast","content":"<p>Invite friends and choose who each person will become.</p>"},{"icon_text":"03","title":"See your side","content":"<p>Receive private knowledge, motives, and moments meant only for you.</p>"},{"icon_text":"04","title":"Change the ending","content":"<p>Act or hesitate and watch every decision reshape the shared world.</p>"}]}]'
WHERE p.page_code='HOME' AND s.section_code='HOW' AND (s.rows_json IS NULL OR s.rows_json='');
